public static GUPPriceEngineTradeAgreementLineFilter getInstance()
{
    return new GUPPriceEngineTradeAgreementLineFilter();
}

    public List filterJournalLineList (SalesTable _salesTable,
        SalesLine _salesLine,
        List _allJournalLineList,
        Set _journalLineRecIdSet,
        str _priceComponentCodeName,
        GUPPriceEngineAttributeGroupPriorityCache _priorityCache)
    {
        InventDim inventDim = _salesLine.inventDim();
        SalesPurchLineInterface salesPurchLineInterface = _salesLine.salesPurchLineInterface();

        PriceDiscParameters parameters = PriceDiscParameters::construct();
        parameters.initFromSalesPurchLineInterface(salesPurchLineInterface, inventDim);

        boolean ignorePriority = this.checkIgnorePriority();
        
        List filteredAggregationList;
        if (ignorePriority)
        {
            return this.filterTradeAgreementLineIgnorePriority(
                    _salesTable,
                    _salesLine,
                    _allJournalLineList,
                    _journalLineRecIdSet,
                    parameters,
                    inventDim);
        } 
        else
        {
            return this.filterTradeAgreementLineWithPriority(
                    _salesTable,
                    _salesLine,
                    _allJournalLineList,
                    _journalLineRecIdSet,
                    _priceComponentCodeName,
                    _priorityCache, 
                    parameters, 
                    inventDim);
        }
    }

    private List filterTradeAgreementLineIgnorePriority(SalesTable _salesTable,
        SalesLine _salesLine,
        List _allJournalLineList,
        Set _journalLineRecIdSet,
        PriceDiscParameters _parameters,
        InventDim _inventDim)
    {
        List filteredAggregationList = new List(Types::AnyType);
        ListEnumerator listEnumerator = _allJournalLineList.getEnumerator();

        while (listEnumerator.moveNext())
        {
            GUPPriceEngineTradeAgreementLine line = listEnumerator.current();

            if (!this.lineValid(line, _salesTable, _salesLine, _parameters, _inventDim))
            {
                continue;
            }
         
            // Record 'valid' journal lines.
            _journalLineRecIdSet.add(line.parmJournalLineRecId());

            // Only price is used in compare, so no competing lines & priority is default to 0.
            GUPPriceEngineTradeAgreementLineAggregation aggregation = new GUPPriceEngineTradeAgreementLineAggregation();
            aggregation.addCompeteLine(line,
                0, 
                this.getJournalLinePrice(line, _salesLine));
            filteredAggregationList.addEnd(aggregation);
        }

        GUPListSorter listSorter = GUPListSorter::getInstance();
        GUPComparatorTradeAgreementLineAggregationPriceOnly priceOnlyComparator = new GUPComparatorTradeAgreementLineAggregationPriceOnly();

        filteredAggregationList = listSorter.sortList(filteredAggregationList, priceOnlyComparator);

        return filteredAggregationList;
    }

    private List filterTradeAgreementLineWithPriority(SalesTable _salesTable,
        SalesLine _salesLine,
        List _allJournalLineList,
        Set _journalLineRecIdSet,
        str _priceComponentCodeName,
        GUPPriceEngineAttributeGroupPriorityCache _priorityCache,
        PriceDiscParameters _parameters, 
        InventDim _inventDim)
    {
        // Value = GUPTradeAgreementJournalLineAggregationObject.
        Map competeJournalLineTempMap = new Map(Types::String, Types::AnyType);
        ListEnumerator listEnumerator = _allJournalLineList.getEnumerator();

        while (listEnumerator.moveNext())
        {
            GUPPriceEngineTradeAgreementLine line = listEnumerator.current();

            if (!this.lineValid(line, _salesTable, _salesLine, _parameters, _inventDim))
            {
                continue;
            }

            // Stores compete journal lines in same object.
            str attributeGroupKey = line.parmAttributeGroupKey();

            GUPPriceEngineTradeAgreementLineAggregation aggregation = null;
            if (competeJournalLineTempMap.exists(attributeGroupKey))
            {
                GUPPriceEngineTradeAgreementLineAggregation competeAggregation = competeJournalLineTempMap.lookup(attributeGroupKey);

                // Extra check to prevent hash collision.
                if (competeAggregation.canAddAsCompeteLine(line))
                {
                    aggregation = competeAggregation;
                }

            }
            
            if (aggregation == null)
            {
                aggregation = new GUPPriceEngineTradeAgreementLineAggregation();
                competeJournalLineTempMap.add(attributeGroupKey, aggregation);
            }

            // Record 'valid' journal lines.
            _journalLineRecIdSet.add(line.parmJournalLineRecId());
            aggregation.addCompeteLine(line,
                _priorityCache.getLinePriority(line, _priceComponentCodeName),
                this.getJournalLinePrice(line, _salesLine));
        }

        
        List filteredAggregationList = new List(Types::AnyType);
        MapEnumerator mapEnumerator = competeJournalLineTempMap.getEnumerator();
        while (mapEnumerator.moveNext())
        {
            GUPPriceEngineTradeAgreementLineAggregation aggregation = mapEnumerator.currentValue();

            if (aggregation.parmListLength() > 1)
            {
                // Sort compete lines by attribute priority, then by line price.
                aggregation.sortJournalLineList();
            }

            filteredAggregationList.addEnd(aggregation);
        }

        GUPListSorter listSorter = GUPListSorter::getInstance();
        GUPComparatorTradeAgreementLineAggregation aggregationComparator = new GUPComparatorTradeAgreementLineAggregation();

        filteredAggregationList = listSorter.sortList(filteredAggregationList, aggregationComparator);

        return filteredAggregationList;
    }

    /// <summary>
    /// Checking fixed parameters from PriceDiscTable.
    /// Return true if current journal line may apply to given salesLine.
    /// Customized pricing attribute is checked later.
    /// </summary>
    /// <param name = "_line">PriceDiscTable record.</param>
    /// <param name = "_salesTable">Header data.</param>
    /// <param name = "_salesLine">Line data.</param>
    /// <param name = "_parameters">Parameter created from salesPurchline and inventDim.</param>
    /// <param name = "_inventDim">Invent data.</param>
    /// <returns>True if journal line may apply.</returns>
    private boolean lineValid (GUPPriceEngineTradeAgreementLine _line,
        SalesTable _salesTable,
        SalesLine _salesLine,
        PriceDiscParameters _parameters,
        InventDim _inventDim)
    {
        PriceDiscTable priceDisc = _line.parmPriceDiscTable();
        FromDate fromDate = priceDisc.FromDate;
        ToDate toDate = priceDisc.ToDate;
        AmountQty quantityAmountFrom = priceDisc.QuantityAmountFrom;
        AmountQuantityTo quantityAmountTo = priceDisc.QuantityAmountTo;

        if (!this.doesDateQualifyForFindingTradeAgreement(_parameters, fromDate, toDate)
             || !this.doesUnitIdQualify(_line, _salesLine.salesUnit)
             || !this.doesQuantityQualifyForFindingTradeAgreement(_parameters, quantityAmountFrom, quantityAmountTo)
             || !this.isIncludedByTradeAgreement(_line, _salesTable, _salesLine)
             || !this.checkAdditionalQualificationForFindingTradeAgreement(_parameters, priceDisc))
        {
            return false;
        }

        return this.checkInventDims(_line, _inventDim);
    }

/// <summary>
/// This method will check and compare the date and can be overwritten to meet customized needs.
/// </summary>
/// <param name = "_parameters">Pre-build parameters from PriceDiscTable.</param>
/// <param name = "_fromDate">From date.</param>
/// <param name = "_toDate">To date.</param>
/// <returns>
/// True if it meets the date conditions; otherwise, false.
/// </returns>
private boolean doesDateQualifyForFindingTradeAgreement(PriceDiscParameters _parameters, FromDate _fromDate, ToDate _toDate)
{
    return ((_parameters.parmPriceDiscDate() >= _fromDate || !_fromDate)
        && (_parameters.parmPriceDiscDate() <= _toDate || !_toDate));
}

    /// <summary>
    /// This method will check and compare the quantity and can be overwritten to meet customized needs.
    /// </summary>
    /// <param name = "_parameters">Pre-build parameters from PriceDiscTable.</param>
    /// <param name = "_qtyFrom">A value of quantity.</param>
    /// <param name = "_qtyTo">A value of quantity.</param>
    /// <returns>
    /// True if it meets the quantity conditions; otherwise, false.
    /// </returns>
    private boolean doesQuantityQualifyForFindingTradeAgreement(PriceDiscParameters _parameters,
        AmountQty _qtyFrom, AmountQuantityTo _qtyTo)
    {
        Qty absQty = abs(_parameters.parmQty());

        if (_parameters.parmUseRetailPricing())
        {
            absQty += abs(_parameters.parmRetailGroupQty());
        }
        return (_qtyFrom <= absQty && (_qtyTo > absQty || (_qtyTo == 0)));
    }

    /// <summary>
    /// This method will check additional conditions for PriceDisc for retail scenario, and can be overwritten to meet customized needs.
    /// </summary>
    /// <param name = "_parameters">Pre-build parameters from PriceDiscTable.</param>
    /// <param name = "_priceDiscTable">The PriceDisc record to check.</param>
    /// <returns>true if it meets retail condition; otherwise, false.</returns>
    private boolean checkAdditionalQualificationForFindingTradeAgreement(PriceDiscParameters _parameters, PriceDiscTable _priceDiscTable)
    {
        boolean additionalCheckResult = true;

        if (_parameters.parmUseRetailPricing())
        {
            InventDim priceDiscDim = InventDim::find(_priceDiscTable.InventDimId);
            //InventTableModule module = InventTableModule::find(_priceDiscTable.ItemRelation, ModuleInventPurchSales::Sales);

            // Retail pricing engine will not apply the trade agreements if:
            // both site and location are set;
            if (priceDiscDim.InventSiteId && priceDiscDim.InventLocationId)
            {
                additionalCheckResult = false;
            }
        }

        return additionalCheckResult;
    }

private boolean checkInventDims (GUPPriceEngineTradeAgreementLine _journalLine, InventDim _inventDim)
{
    // Assume no extra filter is required.
    return true;
}

    private real getJournalLinePrice (GUPPriceEngineTradeAgreementLine _journalLine,
        SalesLine _salesLine)
    {
        PriceDiscTable priceDiscTable = _journalLine.parmPriceDiscTable();
        PriceConvertFactory priceConvertFactory = PriceConvertFactory::newItemPrice(
            _salesLine.ItemId,
            priceDiscTable.UnitId,
            priceDiscTable.price(),
            priceDiscTable.priceUnit(),
            priceDiscTable.markup(),
            priceDiscTable.priceQty(),
            priceDiscTable.Currency);

        priceConvertFactory.parmNewCurrencyCode(_salesLine.CurrencyCode);
        priceConvertFactory.parmNewUnitId(_salesLine.SalesUnit);
                       
        PriceConvert priceConvert = priceConvertFactory.priceConvert();

        Price price = priceConvert.parmPrice();
        return this.dealSmartRounding(price, _salesLine, priceDiscTable);
    }

private real dealSmartRounding(Price _price, SalesLine _salesLine, PriceDiscTable _priceDiscTable)
{
    // TODO smart rounding.
    // Return unit price, so no quantity need to be considered.
    return _price;
}

/// <summary>
/// When searchAgain set to Yes, ignore all priority settings, and consider price only.
/// </summary>
/// <returns>True if priority should be ignored.</returns>
private boolean checkIgnorePriority()
{
    return GUPParameters::find().PriceDiscSearchAgainDefault == NoYes::Yes;
}
